//! Loading YAML entries from `entries/{data,tools,operations}/*.yaml`.

use anyhow::{Context, Result};
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};

/// Sub-directories of the entries dir and the `kind` each must contain.
/// Implementations are not loaded from here: they will be generated by the
/// engine harvesters into their own folder (design set, section 6).
pub const KIND_DIRS: &[(&str, &str)] = &[
    ("data", "data"),
    ("tools", "tool"),
    ("operations", "operation"),
];

/// Kinds published in the `entries` table and `index.json` `entries` list,
/// which Columbus servers read today. Other kinds go in their own tables so
/// that existing readers see exactly what they saw before.
pub const CATALOGUE_KINDS: &[&str] = &["data", "tool"];

/// The `kind` of an entry value, if it has one.
pub fn kind_of(v: &Value) -> Option<&str> {
    v.get("kind").and_then(Value::as_str)
}

/// One entry file as loaded from disk.
#[derive(Debug, Clone)]
pub struct EntryFile {
    pub path: PathBuf,
    /// File name without `.yaml`.
    pub stem: String,
    /// The `kind` implied by the directory the file sits in.
    pub dir_kind: &'static str,
    /// Parsed YAML as JSON, or the parse error message.
    pub value: Result<Value, String>,
}

impl EntryFile {
    pub fn display(&self) -> String {
        self.path.display().to_string()
    }
}

/// Convert YAML text into a JSON value (YAML must be a mapping at the top level).
pub fn parse_yaml(text: &str) -> Result<Value, String> {
    let yaml: serde_norway::Value = serde_norway::from_str(text).map_err(|e| e.to_string())?;
    let json = serde_json::to_value(yaml).map_err(|e| e.to_string())?;
    if !json.is_object() {
        return Err("top level of an entry must be a mapping".into());
    }
    Ok(json)
}

/// Load every `*.yaml` / `*.yml` under the known kind directories, sorted by path.
/// Files elsewhere in the entries dir are reported by the validator, not loaded.
pub fn load_dir(dir: &Path) -> Result<Vec<EntryFile>> {
    if !dir.is_dir() {
        anyhow::bail!("entries directory {} does not exist", dir.display());
    }
    let mut out = Vec::new();
    for (sub, kind) in KIND_DIRS {
        let d = dir.join(sub);
        if !d.is_dir() {
            continue;
        }
        let mut paths: Vec<PathBuf> = fs::read_dir(&d)
            .with_context(|| format!("reading {}", d.display()))?
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| {
                p.is_file()
                    && matches!(
                        p.extension().and_then(|e| e.to_str()),
                        Some("yaml") | Some("yml")
                    )
            })
            .collect();
        paths.sort();
        for path in paths {
            let stem = path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or_default()
                .to_string();
            let value = fs::read_to_string(&path)
                .map_err(|e| e.to_string())
                .and_then(|t| parse_yaml(&t));
            out.push(EntryFile {
                path,
                stem,
                dir_kind: kind,
                value,
            });
        }
    }
    Ok(out)
}

fn yaml_files(dir: &Path) -> Result<Vec<PathBuf>> {
    let mut paths: Vec<PathBuf> = fs::read_dir(dir)
        .with_context(|| format!("reading {}", dir.display()))?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| {
            p.is_file()
                && matches!(
                    p.extension().and_then(|e| e.to_str()),
                    Some("yaml") | Some("yml")
                )
        })
        .collect();
    paths.sort();
    Ok(paths)
}

fn sub_dirs(dir: &Path) -> Result<Vec<PathBuf>> {
    let mut dirs: Vec<PathBuf> = fs::read_dir(dir)
        .with_context(|| format!("reading {}", dir.display()))?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.is_dir())
        .collect();
    dirs.sort();
    Ok(dirs)
}

fn stem_of(path: &Path) -> String {
    path.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or_default()
        .to_string()
}

/// A problem found while loading, before schema validation (a mapping with
/// no harvested implementation, a mapping that sets harvested fields, ...).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoadProblem {
    pub file: String,
    pub message: String,
}

/// Fields a person may set in `mappings/<software>/<id>.yaml`. Everything
/// else (name, call, parameters, signatures, harvest, ...) comes from the
/// harvester and is replaced on every re-harvest.
pub const MAPPING_FIELDS: &[&str] = &[
    "id",
    "variant_of",
    "implements",
    "crosswalk",
    "presets",
    "differences",
    "effects",
    "requires",
    "notes",
    "review",
];

/// Load harvested implementations from `implementations/<software>/*.yaml`
/// and merge the person-written parts from `mappings/<software>/<id>.yaml`.
/// A missing directory means none. Each implementation must sit in the
/// folder named after its `software`; every mapping must match an
/// implementation (a stale mapping after a re-harvest is reported, not dropped).
pub fn load_implementations(
    dir: &Path,
    mappings: &Path,
) -> Result<(Vec<EntryFile>, Vec<LoadProblem>)> {
    let mut files = Vec::new();
    let mut problems = Vec::new();
    if dir.is_dir() {
        for folder in sub_dirs(dir)? {
            let software = stem_of(&folder);
            for path in yaml_files(&folder)? {
                let value = fs::read_to_string(&path)
                    .map_err(|e| e.to_string())
                    .and_then(|t| parse_yaml(&t));
                if let Ok(v) = &value {
                    let declared = v.get("software").and_then(Value::as_str);
                    if declared != Some(software.as_str()) {
                        problems.push(LoadProblem {
                            file: path.display().to_string(),
                            message: format!(
                                "software {:?} does not match its folder '{software}'",
                                declared.unwrap_or("")
                            ),
                        });
                    }
                }
                files.push(EntryFile {
                    stem: stem_of(&path),
                    path,
                    dir_kind: "implementation",
                    value,
                });
            }
        }
    }
    // Variants (`variant_of`) copy the harvested description, never a mapped one.
    let harvested: Vec<(String, String, Value)> = files
        .iter()
        .filter_map(|f| {
            let software = f.path.parent().map(stem_of)?;
            Some((software, f.stem.clone(), f.value.as_ref().ok()?.clone()))
        })
        .collect();
    let mut variants: Vec<EntryFile> = Vec::new();
    if mappings.is_dir() {
        for folder in sub_dirs(mappings)? {
            let software = stem_of(&folder);
            for path in yaml_files(&folder)? {
                let display = path.display().to_string();
                let mut problem = |message: String| {
                    problems.push(LoadProblem {
                        file: display.clone(),
                        message,
                    })
                };
                let mapping = match fs::read_to_string(&path)
                    .map_err(|e| e.to_string())
                    .and_then(|t| parse_yaml(&t))
                {
                    Ok(m) => m,
                    Err(e) => {
                        problem(format!("YAML parse error: {e}"));
                        continue;
                    }
                };
                let stem = stem_of(&path);
                if mapping.get("id").and_then(Value::as_str) != Some(stem.as_str()) {
                    problem(format!("id must be '{stem}', the file name"));
                    continue;
                }
                if let Some(base) = mapping.get("variant_of").and_then(Value::as_str) {
                    // A second operation done by the same harvested tool, with its own
                    // presets: a new implementation entry `<base>--<suffix>`.
                    if !stem.starts_with(&format!("{base}--")) {
                        problem(format!("a variant's id must start with '{base}--'"));
                        continue;
                    }
                    let Some((_, _, original)) = harvested
                        .iter()
                        .find(|(sw, st, _)| sw == &software && st == base)
                    else {
                        problem(format!(
                            "variant_of '{base}': no harvested implementation in implementations/{software}/"
                        ));
                        continue;
                    };
                    let mut entry = original.clone();
                    if let Value::Object(obj) = &mut entry {
                        obj.insert("id".into(), Value::String(stem.clone()));
                        for (k, v) in mapping.as_object().into_iter().flatten() {
                            if !MAPPING_FIELDS.contains(&k.as_str()) {
                                problem(format!("a mapping may not set '{k}'"));
                            } else if k != "id" {
                                obj.insert(k.clone(), v.clone());
                            }
                        }
                    }
                    variants.push(EntryFile {
                        stem: stem.clone(),
                        path: path.clone(),
                        dir_kind: "implementation",
                        value: Ok(entry),
                    });
                    continue;
                }
                let target = files.iter_mut().find(|f| {
                    f.stem == stem && f.path.parent().map(stem_of).as_deref() == Some(&software)
                });
                let Some(target) = target else {
                    problem(format!(
                        "no harvested implementation '{stem}' in implementations/{software}/ \
                         (renamed or removed by the engine? update or delete this mapping)"
                    ));
                    continue;
                };
                let Ok(Value::Object(entry)) = &mut target.value else {
                    continue;
                };
                for (k, v) in mapping.as_object().into_iter().flatten() {
                    if !MAPPING_FIELDS.contains(&k.as_str()) {
                        problem(format!(
                            "a mapping may not set '{k}': it comes from the harvester \
                             (a mapping may set {})",
                            MAPPING_FIELDS[1..].join(", ")
                        ));
                    } else if k != "id" {
                        entry.insert(k.clone(), v.clone());
                    }
                }
            }
        }
    }
    files.extend(variants);
    Ok((files, problems))
}

/// Return only the successfully parsed entries (used after validation passed).
pub fn values(files: &[EntryFile]) -> Vec<Value> {
    files
        .iter()
        .filter_map(|f| f.value.as_ref().ok().cloned())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_mapping() {
        let v = parse_yaml("id: a\nkind: tool\n").unwrap();
        assert_eq!(v["id"], "a");
    }

    #[test]
    fn rejects_non_mapping() {
        assert!(parse_yaml("- a\n- b\n").is_err());
        assert!(parse_yaml("id: [unclosed\n").is_err());
    }

    #[test]
    fn dates_stay_strings() {
        let v = parse_yaml("last_verified: 2026-01-02\n").unwrap();
        assert_eq!(v["last_verified"], "2026-01-02");
    }
}
